/**
 * Generates apps/mobile/src/components/charts/globe/land-dots.ts: the land of the world as dots
 * for the globe of Investimentos, the same dots as the web app (world-atlas 110m, 1.8°, rows
 * offset like a honeycomb), plus the visual center of each country.
 * Run from a folder with the geo tools installed:
 *   npm i world-atlas@2 topojson-client@3 d3-geo@3 && node /path/to/generate-land-dots.mjs out.ts
 * then copy the generated file over the app's land-dots.ts.
 */
import fs from 'node:fs';
import { feature } from 'topojson-client';
import { geoBounds, geoCentroid, geoContains } from 'd3-geo';

const topo = JSON.parse(fs.readFileSync('node_modules/world-atlas/countries-110m.json', 'utf8'));
const countries = feature(topo, topo.objects.countries).features.map((f) => ({
  code: Number(f.id) || 0,
  feature: f,
  bounds: geoBounds(f),
}));

/** Spacing in degrees (about equal area: longitude opens up near the poles). */
const STEP = 1.8;

function inBounds([[w, s], [e, n]], lon, lat) {
  if (lat < s || lat > n) return false;
  return w <= e ? lon >= w && lon <= e : lon >= w || lon <= e; // crosses the antimeridian
}

const dots = [];
for (let lat = -58; lat <= 84; lat += STEP) {
  const step = STEP / Math.max(Math.cos((lat * Math.PI) / 180), 0.2);
  const offset = (Math.round(lat / STEP) % 2) * (step / 2); // alternate rows, like a honeycomb
  for (let lon = -180 + offset; lon < 180; lon += step) {
    const hit = countries.find(
      (c) => inBounds(c.bounds, lon, lat) && geoContains(c.feature, [lon, lat]),
    );
    if (hit) dots.push(Math.round(lat * 10), Math.round(lon * 10), hit.code);
  }
}

const centers = {};
for (const { code, feature: f } of countries) {
  if (!code) continue;
  const [lon, lat] = geoCentroid(f);
  centers[code] = [Math.round(lat * 10) / 10, Math.round(lon * 10) / 10];
}

const out = `/**
 * Land of the world as dots, in triples: latitude×10, longitude×10, country (ISO 3166-1
 * numeric). The same dots as the web app's globe: world-atlas 110m (Natural Earth, public
 * domain), every ${STEP}°, rows offset like a honeycomb. Generated by
 * tools/geo/generate-land-dots.mjs — regenerate instead of editing by hand.
 */
export const LAND_DOTS = new Int16Array([${dots.join(',')}]);

/** Visual center of each country (lat, lon) by ISO 3166-1 numeric code. */
export const COUNTRY_CENTERS: Readonly<Record<number, readonly [number, number]>> = ${JSON.stringify(centers)};
`;
fs.writeFileSync(process.argv[2] ?? 'land-dots.ts', out);
// eslint-disable-next-line no-console -- CLI script: reports what it generated.
console.log('dots', dots.length / 3, 'bytes', out.length);
